        self.tag=Some(TagState::new(p,false));self.parse_tag(limit,visitor,cancel)
    }
    fn parse_pending<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
        let pending=core::mem::replace(&mut self.pending,Pending::None);
        match pending{
            Pending::None=>true,
            Pending::Text{start,mut pos,mut nonspace,mut first_nonspace}=>{
                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Text{start,pos,nonspace,first_nonspace};self.canceled=true;return false}
                    if self.source[pos]==b'<'{break}
                    if pos+3<=limit&&self.source.get(pos..pos+3)==Some(b"]]>"){self.fail(XmlError::MalformedSyntax,pos);return false}
                    if pos+3>limit&&limit<self.source.len(){break}
