                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Comment{start,pos};self.canceled=true;return false}
                    if pos+3<=limit&&self.source.get(pos..pos+3)==Some(b"-->"){let t=XmlToken{kind:TokenKind::Comment,source:span(start,pos+3),value:span(start+4,pos),depth:self.depth,..XmlToken::default()};self.count_node(start);if !self.emit(t,start,visitor){return false}self.cursor=pos+3;return true}
