#[test]
fn xml_character_ranges_and_whitespace_match_xml_10() {
    for cp in [0x9, 0xa, 0xd, 0x20, 0xd7ff, 0xe000, 0xfffd, 0x10000, 0x10ffff] {
        assert!(is_xml_char(cp), "U+{cp:04X}");
    }
    for cp in [0, 8, 0xb, 0x1f, 0xd800, 0xdfff, 0xfffe, 0x10000 + 0x100000] {
        assert!(!is_xml_char(cp), "U+{cp:04X}");
    }
    for byte in [b' ', b'\t', b'\r', b'\n'] { assert!(is_xml_whitespace(byte)); }
    for byte in [0, b'\x0b', b'\x0c', b'\x85'] { assert!(!is_xml_whitespace(byte)); }
}

#[test]
fn name_start_and_name_char_ranges_match_xml_10() {
    for cp in [b':' as u32, b'_' as u32, b'A' as u32, 0xc0, 0xd6, 0xd8, 0xf6,
        0xf8, 0x2ff, 0x370, 0x37d, 0x37f, 0x1fff, 0x200c, 0x200d, 0x2070,
        0x218f, 0x2c00, 0x2fef, 0x3001, 0xd7ff, 0xf900, 0xfdcf, 0xfdf0,
        0xfffd, 0x10000, 0xeffff] {
        assert!(is_name_start(cp), "U+{cp:04X}");
        assert!(is_name_char(cp), "U+{cp:04X}");
    }
    for cp in [0xb7, b'-' as u32, b'.' as u32, b'0' as u32, 0x300, 0x36f, 0x203f, 0x2040] {
        assert!(!is_name_start(cp), "U+{cp:04X}");
        assert!(is_name_char(cp), "U+{cp:04X}");
    }
    for cp in [0x2f, 0x37e, 0x200e, 0xd800, 0xfdd0, 0xf0000, 0xf0000 + 0x10000] {
        assert!(!is_name_start(cp), "U+{cp:04X}");
        assert!(!is_name_char(cp), "U+{cp:04X}");
    }
}

#[test]
fn every_unicode_scalar_matches_the_xml_10_range_tables() {
    const CHAR_RANGES: &[(u32, u32)] = &[(0x9, 0xa), (0xd, 0xd), (0x20, 0xd7ff), (0xe000, 0xfffd), (0x10000, 0x10ffff)];
    const NAME_START_RANGES: &[(u32, u32)] = &[
        (0x3a, 0x3a), (0x41, 0x5a), (0x5f, 0x5f), (0x61, 0x7a), (0xc0, 0xd6),
        (0xd8, 0xf6), (0xf8, 0x2ff), (0x370, 0x37d), (0x37f, 0x1fff),
        (0x200c, 0x200d), (0x2070, 0x218f), (0x2c00, 0x2fef), (0x3001, 0xd7ff),
        (0xf900, 0xfdcf), (0xfdf0, 0xfffd), (0x10000, 0xeffff),
    ];
    const NAME_EXTRA_RANGES: &[(u32, u32)] = &[
        (0x2d, 0x2e), (0x30, 0x39), (0xb7, 0xb7), (0x300, 0x36f), (0x203f, 0x2040),
    ];
    for cp in 0..=0x10ffff {
        let expected_char = CHAR_RANGES.iter().any(|&(start, end)| (start..=end).contains(&cp));
        let expected_start = NAME_START_RANGES.iter().any(|&(start, end)| (start..=end).contains(&cp));
        let expected_name = expected_start || NAME_EXTRA_RANGES.iter().any(|&(start, end)| (start..=end).contains(&cp));
        assert_eq!(is_xml_char(cp), expected_char, "Char U+{cp:04X}");
        assert_eq!(is_name_start(cp), expected_start, "NameStartChar U+{cp:04X}");
        assert_eq!(is_name_char(cp), expected_name, "NameChar U+{cp:04X}");
    }
}

#[test]
fn utf8_decoder_accepts_scalars_and_preserves_position_on_bad_input() {
    let valid: &[(&[u8], u32)] = &[
        (b"A", 0x41), (&[0xc2, 0xa2], 0xa2), (&[0xe2, 0x82, 0xac], 0x20ac),
        (&[0xf0, 0x9f, 0x98, 0x80], 0x1f600),
    ];
    for &(bytes, cp) in valid {
        assert_eq!(utf8_next(bytes, 0), Some((cp, bytes.len())));
        assert_eq!(utf8_next(bytes, bytes.len()), None);
    }
    for bytes in [
        &[0x80][..], &[0xc0, 0xaf], &[0xc2], &[0xc2, b'A'], &[0xe0, 0x80, 0x80],
        &[0xed, 0xa0, 0x80], &[0xf0, 0x80, 0x80, 0x80], &[0xf4, 0x90, 0x80, 0x80],
        &[0xf5, 0x80, 0x80, 0x80],
    ] {
        assert_eq!(utf8_next(bytes, 0), None, "{bytes:?}");
    }
}

fn collect_with_budget(source: &[u8], budget: usize) -> (ReaderStatus, ReaderProgress, Vec<ReaderTag>) {
    let mut reader = XmlReader::new(source).expect("within source limit");
    let mut tags = Vec::new();
    loop {
        let before = reader.progress().bytes_read;
        let status = reader.step(budget, |tag| { tags.push(tag); true });
        let progress = reader.progress();
        assert!(progress.bytes_read - before <= budget.min(MAX_READER_STEP_BYTES));
        if status != ReaderStatus::Ok { return (status, progress, tags); }
    }
}

